/**
 * opc-runtime-bridge · DSH host plugin（ADR-0005 §1）
 *
 * 把 DSH 进程内的 `sessionController` 封装为一组仅回环可达的 HTTP 控制 API，
 * 供 workbench-server 的 dshAdapter 跨进程驱动：
 *
 *   POST   /opc-runtime/v1/sessions                    {text?} -> create + follow 缓冲循环 + prompt
 *   GET    /opc-runtime/v1/sessions/:id/events?since=N -> 环形事件缓冲（完整帧 + index）
 *   POST   /opc-runtime/v1/sessions/:id/messages       {text}  -> controller.prompt（追加指令）
 *   POST   /opc-runtime/v1/sessions/:id/cancel                 -> controller.cancel
 *   GET    /opc-runtime/v1/sessions/:id/result         -> 由事件流派生 {status,text,usage,error}
 *   GET    /opc-runtime/v1/health                      -> 桥存活探针
 *
 * 安全姿态与阶段 0 的 opc-probe 一致：插件路由绕过宿主 token 门，因此插件
 * 自挡跨站请求（sec-fetch-site / Origin 同源）且写请求必须是 application/json；
 * 宿主 webServer 仅绑定 127.0.0.1，路由不可从机器外到达。仅允许 GET/POST。
 *
 * 该文件是纯 JS ESM，不参与 workbench 的 tsc；只依赖 Node 内置模块与宿主注入的
 * `webServer` / `sessionController`，不得 import workbench 的 TS 代码。
 */
import { randomUUID } from 'node:crypto'
import { isAbsolute, join, relative, resolve } from 'node:path'
import { homedir } from 'node:os'

export const name = 'opc-runtime-bridge'
export const inject = ['webServer', 'sessionController', 'agentPresets']

const DEFAULT_ROUTE_PREFIX = '/opc-runtime/v1'
const DEFAULT_MAX_BODY_BYTES = 262144
const DEFAULT_MAX_FRAMES = 2000
const MAX_SESSIONS = Math.max(8, Number(process.env.OPC_BRIDGE_MAX_SESSIONS || 64))
const BRIDGE_VERSION = '0.3.0-auto-review'
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))
const WRITE_TOOLS = new Set(['write', 'edit', 'apply_patch', 'bash', 'pwsh'])
/** Auto review 由内置插件 @deepseek-ai/dsh-experimental-auto-review 提供；可用 OPC_AUTO_REVIEW=0 关闭。 */
const WANT_AUTO_REVIEW = String(process.env.OPC_AUTO_REVIEW || '1') !== '0'
/** 复核等待上限：超时按拒绝处理（fail-closed）。 */
const APPROVAL_WAIT_MS = Math.max(30_000, Number(process.env.OPC_APPROVAL_WAIT_MS || 600_000))
/** 默认允许所有权限：所有工具调用和审批请求直接放行；需要恢复严格模式时设 OPC_ALLOW_ALL=0。 */
const ALLOW_ALL = String(process.env.OPC_ALLOW_ALL || '1') !== '0'
/** 红线文件：无论 Auto review 怎么判，都要老板确认。 */
const SENSITIVE_TARGET =
  /(^|[\\/])(\.env(\.[^\\/]*)?|\.git|id_rsa|id_ed25519|\.ssh|credentials|secrets?|settings\.json|store\.json|agent-tools\.token|\.npmrc|\.pypirc)([\\/]|$)/i

/** 读取工具参数对象。 */
function toolArgs(exec) {
  const args = exec && exec.arguments
  return args && typeof args === 'object' && !Array.isArray(args) ? args : {}
}

/**
 * 确定性红线：敏感文件、工作区外的文件目标。
 * 命中时返回中文原因，交给 DSH 审批服务询问老板；未命中返回空串。
 */
function redLineReason(exec, cwd) {
  const name = String((exec && exec.name) || '')
  const args = toolArgs(exec)
  const paths = []
  let text = ''
  if (name === 'bash' || name === 'pwsh') {
    text = String(args.command || args.script || '')
  } else if (name === 'apply_patch') {
    text = String(args.input || '')
  } else {
    for (const key of ['file_path', 'path', 'file', 'directory', 'target']) {
      if (typeof args[key] === 'string' && args[key].length > 0) paths.push(args[key])
    }
    text = paths.join('\n')
  }
  if (text.trim().length === 0) return ''
  if (SENSITIVE_TARGET.test(text)) {
    return '涉及密钥 / 凭据 / 配置数据文件（.env、.git、store.json、settings.json、token 等），需要老板确认'
  }
  if (!cwd || paths.length === 0) return ''
  const readOnly = !WRITE_TOOLS.has(name)
  // 公司内部的工作区（员工工位、项目工作区、公司资料）对员工默认放行：
  // 这是员工完成本职工作的必要范围，不能每一份项目文档的读写都弹审批。
  const roots = [cwd]
  const projectRoot = cwd.replace(/[\\/]workstations[\\/][^\\/]+[\\/]?$/, '')
  if (projectRoot !== cwd) roots.push(projectRoot)
  const dataDir = String(process.env.OC_DATA_DIR || 'D:\\一人公司工作区\\data').trim()
  if (dataDir) roots.push(join(dataDir, 'workspaces'))
  if (readOnly) {
    // WorkBuddy 专家 / 技能市场目录：只读放行，招聘和检索时不再触发审批。
    const home = homedir()
    roots.push(join(home, '.workbuddy'))
    roots.push(join(home, 'WorkBuddy'))
    if (process.env.APPDATA) roots.push(join(process.env.APPDATA, 'WorkBuddy'))
  }
  for (const target of paths) {
    if (!isAbsolute(target)) continue
    const absolute = resolve(target)
    if (roots.some((root) => {
      const rel = relative(root, absolute)
      return rel === '' || (!rel.startsWith('..') && !isAbsolute(rel))
    })) continue
    return `目标文件不在员工工作区（${cwd}）内，需要老板确认`
  }
  return ''
}

// ---------------------------------------------------------------------------
// HTTP helpers
// ---------------------------------------------------------------------------

/** 同源 / 回环闸门（沿用 opc-probe 已验证模式） */
function guardRequest(req) {
  const headers = req.headers || {}
  const site = String(headers['sec-fetch-site'] || '')
  if (site === 'cross-site' || site === 'same-site') {
    return { ok: false, code: 'CROSS_ORIGIN', error: 'refuse cross-site request' }
  }
  const origin = headers.origin
  if (origin) {
    let originHost = ''
    try {
      originHost = new URL(origin).host
    } catch {
      return { ok: false, code: 'CROSS_ORIGIN', error: 'illegal Origin' }
    }
    if (!headers.host || originHost !== headers.host) {
      return { ok: false, code: 'CROSS_ORIGIN', error: 'same-origin check failed' }
    }
  }
  const method = String(req.method || 'GET').toUpperCase()
  if (method !== 'GET' && method !== 'HEAD') {
    const type = String(headers['content-type'] || '')
    if (!type.toLowerCase().startsWith('application/json')) {
      return { ok: false, code: 'UNSUPPORTED_MEDIA', error: 'writes must be application/json' }
    }
  }
  return { ok: true }
}

function json(res, status, payload) {
  const body = JSON.stringify(payload)
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' })
  res.end(body)
}

function readJsonBody(req, maxBytes) {
  return new Promise((resolve, reject) => {
    const chunks = []
    let size = 0
    req.on('data', (chunk) => {
      size += chunk.length
      if (size > maxBytes) {
        reject(new Error('body too large'))
        req.destroy()
        return
      }
      chunks.push(chunk)
    })
    req.on('end', () => {
      if (chunks.length === 0) {
        resolve({})
        return
      }
      try {
        const parsed = JSON.parse(Buffer.concat(chunks).toString('utf8'))
        if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
          reject(new Error('body must be a JSON object'))
          return
        }
        resolve(parsed)
      } catch (error) {
        reject(new Error(`invalid JSON body: ${error.message}`))
      }
    })
    req.on('error', reject)
  })
}

function errorMessage(error) {
  return error instanceof Error ? error.message : String(error)
}

// ---------------------------------------------------------------------------
// 事件派生（getResult）
// ---------------------------------------------------------------------------

function eventOf(frame) {
  if (frame && typeof frame === 'object' && frame.type === 'event' && frame.event && typeof frame.event === 'object') {
    return frame.event
  }
  return null
}

function textFromAssistantMessage(data) {
  const content = data && typeof data === 'object' ? data.message && data.message.content : null
  if (!Array.isArray(content)) return ''
  return content
    .filter((part) => part && typeof part === 'object' && part.type === 'text' && typeof part.text === 'string')
    .map((part) => part.text)
    .join('')
}

function usageFromAssistantMessage(data) {
  const usage = data && typeof data === 'object' ? data.usage : null
  if (!usage || typeof usage !== 'object') return null
  const pick = (key) => (typeof usage[key] === 'number' && Number.isFinite(usage[key]) ? usage[key] : null)
  const inputTokens = pick('inputTokens')
  const outputTokens = pick('outputTokens')
  const totalTokens = pick('totalTokens')
  const cacheReadTokens = pick('cacheReadTokens')
  if (inputTokens === null && outputTokens === null && totalTokens === null && cacheReadTokens === null) return null
  return { inputTokens, outputTokens, totalTokens, cacheReadTokens }
}

function deriveResult(session) {
  let text = ''
  let usage = null
  for (const frame of session.frames) {
    const event = eventOf(frame)
    if (!event || event.type !== 'assistant/message') continue
    const candidate = textFromAssistantMessage(event.data)
    if (candidate.length > 0) text = candidate
    const candidateUsage = usageFromAssistantMessage(event.data)
    if (candidateUsage) usage = candidateUsage
  }

  let status
  if (session.status === 'error') status = 'failed'
  else if (session.status === 'cancelled') status = 'cancelled'
  else if (session.status === 'active') status = 'running'
  else if (session.status === 'turn_ended' || session.status === 'closed') {
    status = session.cancelRequested ? 'cancelled' : 'succeeded'
  } else status = 'running'

  return { status, text, usage, error: session.error ?? null }
}

// ---------------------------------------------------------------------------
// apply
// ---------------------------------------------------------------------------

export function apply(ctx, config = {}) {
  const routePrefix = String(config.routePrefix ?? DEFAULT_ROUTE_PREFIX).replace(/\/+$/, '')
  const maxBodyBytes = Number(config.maxBodyBytes ?? DEFAULT_MAX_BODY_BYTES)
  const maxFramesPerSession = Number(config.maxFramesPerSession ?? DEFAULT_MAX_FRAMES)
  const approvalBase = String(
    config.approvalUrl ?? process.env.OPC_APPROVAL_URL ?? 'http://127.0.0.1:4399',
  ).replace(/\/+$/, '')

  ctx.logger?.info?.(`opc-runtime-bridge: apply() entered; prefix ${routePrefix}`)

  const web = ctx.get('webServer')
  const controller = ctx.get('sessionController')
  const agentPresets = ctx.get('agentPresets')
  if (!web || typeof web.register !== 'function') {
    ctx.logger?.warn?.('opc-runtime-bridge: webServer service absent; plugin stays inactive')
    return
  }
  if (!controller) {
    ctx.logger?.warn?.('opc-runtime-bridge: sessionController service absent; plugin stays inactive')
    return
  }
  if (!agentPresets) {
    ctx.logger?.warn?.('opc-runtime-bridge: agentPresets service absent; dynamic presets disabled')
  }

  /** @type {Map<string, any>} sessionId -> 会话记录 */
  const sessions = new Map()
  /** 兼容不同 DSH 版本的 agent 结构：id/sessionId/employeeId/cwd 都能找到会话 */
  function resolveSession(agent) {
    if (!agent) return null
    const direct = sessions.get(agent.id) || sessions.get(agent.sessionId) || sessions.get(agent.session?.id)
    if (direct) return direct
    const values = [...new Set(sessions.values())]
    return values.find((item) => agent.employeeId && item.employeeId === agent.employeeId)
      || values.find((item) => agent.cwd && item.cwd === agent.cwd)
      || (sessions.size === 1 ? values[0] : null)
  }
  /** @type {Map<string, Function>} dynamic preset id -> disposer */
  const dynamicPresets = new Map()

  /** 把一次需要老板确认的调用写入公司审批收件箱，返回 approvalId。 */
  async function requestApproval(session, request, source) {
    const response = await fetch(`${approvalBase}/api/approvals/request`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({
        sessionId: session.sessionId,
        employeeId: session.employeeId || '',
        projectId: session.projectId || '',
        toolName: request.toolName || '',
        callId: request.callId || '',
        reason: request.reason || '',
        source,
        origin: session.turnKind === 'chat' ? 'chat' : 'company',
        risk: source === 'auto-review' ? 'medium' : 'high',
        cwd: session.cwd || '',
        task: session.lastPrompt || '',
      }),
      signal: AbortSignal.timeout(15_000),
    })
    const payload = await response.json().catch(() => ({}))
    if (!response.ok || !payload.ok || typeof payload.approvalId !== 'string') {
      throw new Error(payload.error || `HTTP ${response.status}`)
    }
    return payload.approvalId
  }

  /** 轮询审批结果；超时或取消按拒绝处理（fail-closed）。 */
  async function waitApproval(approvalId, signal) {
    const started = Date.now()
    while (Date.now() - started < APPROVAL_WAIT_MS) {
      if (signal?.aborted) return 'cancelled'
      await sleep(500)
      try {
        const response = await fetch(`${approvalBase}/api/approvals/${encodeURIComponent(approvalId)}`, {
          signal: AbortSignal.timeout(5_000),
        })
        const payload = await response.json().catch(() => ({}))
        if (!response.ok || !payload.ok) throw new Error(payload.error || `HTTP ${response.status}`)
        if (payload.status === 'approved') return 'allowed-once'
        if (payload.status === 'rejected') return 'rejected'
      } catch {
        /* 网络抖动时继续轮询，超时后拒绝 */
      }
    }
    return 'rejected'
  }

  // DSH 原生审批：普通操作直接放行，不再把每条命令都转成老板的审批卡。
  // 真正的红线已由 tools/pre-execute 拦截并写入公司收件箱。
  ctx.on('approval/request', async (request, next) => {
    if (ALLOW_ALL) return 'allowed-once'
    const text = `${request?.reason || ''} ${JSON.stringify(request?.arguments || request?.args || {})}`
    // 沙箱提权（例如从工位沙箱写到项目根目录）必须进公司审批收件箱，
    // 不能因为“公司任务”就自动放行——否则只会在 DSH 对话页闪一下。
    const escalation = /escalate\s+sandbox|danger-full-access|沙箱提权|提升沙箱权限/i.test(text)
    if (!escalation && !SENSITIVE_TARGET.test(text)) return 'allowed-once'
    const session = resolveSession(request?.agent)
    // 非提权的普通敏感请求，公司任务仍自动放行；提权请求一律问老板。
    if (!escalation && session && session.turnKind !== 'chat') return 'allowed-once'
    const fallbackSession = session || {
      sessionId: String(request?.agent?.id || ''),
      employeeId: '',
      projectId: '',
      cwd: '',
      lastPrompt: '',
    }
    let approvalId
    try {
      approvalId = await requestApproval(fallbackSession, request, 'runtime')
    } catch (error) {
      ctx.logger?.warn?.(`opc-runtime-bridge: 审批上报失败：${errorMessage(error)}`)
      return 'rejected'
    }
    return waitApproval(approvalId, request.signal)
  }, { prepend: true })

  ctx.on('tools/pre-execute', async (exec, next) => {
    if (ALLOW_ALL) return next()
    const session = resolveSession(exec.agent)
    // 确定性红线：敏感文件 / 工作区外路径，直接写入公司审批收件箱。
    // 公司任务也必须检查；项目根目录在 redLineReason 的白名单内，不会误拦正常项目写文件。
    // 不能只返回 { kind: 'ask' }：DSH 原生审批弹窗不在一人公司前端里，
    // 老板看不到就会表现为“任务卡在审批、收件箱没有申请”。
    const reason = redLineReason(exec, session?.cwd || '')
    if (reason) {
      const approvalSession = session || {
        sessionId: String(exec.agent?.id || ''),
        employeeId: '',
        projectId: '',
        cwd: '',
        lastPrompt: '',
      }
      let approvalId
      try {
        approvalId = await requestApproval(
          approvalSession,
          { toolName: exec.name, callId: exec.callId, reason },
          'red-line',
        )
      } catch (error) {
        return { kind: 'deny', reason: `审批服务不可用，操作已拒绝：${errorMessage(error)}` }
      }
      const decision = await waitApproval(approvalId, exec.signal)
      if (decision === 'allowed-once') return { kind: 'allow' }
      if (decision === 'cancelled') return { kind: 'cancel' }
      return { kind: 'deny', reason: '老板拒绝了这次操作' }
    }
    // 工作区内的普通写文件 / 终端命令默认放行，不再逐条问老板。
    // 真正需要确认的只有上面的红线：敏感凭据、配置数据、工作区外路径。
    return next()
  })


  function promptSession(session, content, mode = 'queue', requestId = '') {
    touchSession(session)
    session.lastPrompt =
      typeof content === 'string'
        ? content
        : Array.isArray(content)
          ? content
              .filter((part) => part && part.type === 'text')
              .map((part) => part.text)
              .join('\n')
          : ''
    session.prompting = true
    const done = () => {
      session.prompting = false
    }
    return Promise.resolve(
      controller.prompt(
        {
          requestId: requestId || randomUUID(),
          sessionId: session.sessionId,
          mode: mode === 'steer' ? 'steer' : 'queue',
          content: Array.isArray(content) ? content : [{ type: 'text', text: String(content || '') }],
        },
        session.followAbort.signal,
      ),
    ).then(
      (value) => {
        done()
        return value
      },
      (error) => {
        done()
        throw error
      },
    )
  }

  function startFollowLoop(session) {
    session.followLoop = (async () => {
      try {
        for await (const frame of controller.follow(
          { address: { kind: 'session', sessionId: session.sessionId } },
          session.followAbort.signal,
        )) {
          if (session.closed) break
          const index = session.nextFrameIndex
          session.nextFrameIndex += 1
          const stored =
            frame && typeof frame === 'object' && !Array.isArray(frame)
              ? { ...frame, index }
              : { index, type: 'unknown', raw: String(frame) }
          session.lastFrameAt = Date.now()
          // opening snapshot 里带着持久化会话的 cwd / preset，恢复后要回填到桥接记录
          if (stored.type === 'snapshot' && stored.header && typeof stored.header === 'object') {
            if (typeof stored.header.cwd === 'string' && stored.header.cwd) session.cwd = stored.header.cwd
            if (stored.header.agentPreset) session.agentPreset = stored.header.agentPreset
          }
          session.frames.push(stored)
          while (session.frames.length > maxFramesPerSession) session.frames.shift()

          const event = eventOf(stored)
          if (event) {
            const type = String(event.type || '')
            if (type === 'turn/start') {
              session.status = 'active'
              session.turnEnded = false
              session.cancelRequested = false
            } else if (type === 'turn/end') {
              session.status = 'turn_ended'
              session.turnEnded = true
              session.runningJobs?.clear()
            } else if (type === 'job/registered') {
              const jobId = event.data && event.data.jobId
              if (jobId) session.runningJobs?.add(String(jobId))
            } else if (type === 'job/settled') {
              const jobId = event.data && event.data.jobId
              if (jobId) session.runningJobs?.delete(String(jobId))
            }
          }
        }
        if (!session.closed && session.status !== 'error') session.status = 'closed'
      } catch (error) {
        if (!session.followAbort.signal.aborted) {
          session.status = 'error'
          session.error = errorMessage(error)
        }
      }
    })()
  }

  function findSession(id) {
    return sessions.get(id) ?? null
  }

  function touchSession(session) {
    if (session) session.lastUsedAt = Date.now()
  }

  function hasActiveTurn(session) {
    // 只有正在等待模型输出的会话不可回收；turn 结束或从未 prompt 的会话都算空闲
    return Boolean(session && session.prompting)
  }

  function evictSession(id, reason = 'evicted') {
    const session = sessions.get(id)
    if (!session) return false
    if (hasActiveTurn(session)) return false
    session.closed = true
    session.evictedAt = new Date().toISOString()
    session.evictReason = reason
    try {
      session.followAbort.abort()
    } catch {
      /* ignore */
    }
    sessions.delete(id)
    return true
  }

  /** 在达到上限前淘汰最久未使用的空闲会话，返回淘汰数量 */
  function evictIdleSessions(need = 1) {
    if (need <= 0) return 0
    const idle = [...sessions.values()]
      .filter((session) => !hasActiveTurn(session))
      .sort((a, b) => Number(a.lastUsedAt || 0) - Number(b.lastUsedAt || 0))
    let evicted = 0
    for (const session of idle) {
      if (evicted >= need) break
      if (evictSession(session.sessionId)) evicted += 1
    }
    return evicted
  }

  async function handle(req, res, pathname) {
    const gate = guardRequest(req)
    if (!gate.ok) {
      json(res, gate.code === 'UNSUPPORTED_MEDIA' ? 415 : 403, { ok: false, code: gate.code, error: gate.error })
      return
    }
    const method = String(req.method || 'GET').toUpperCase()
    if (method !== 'GET' && method !== 'POST' && method !== 'DELETE') {
      json(res, 405, { ok: false, code: 'METHOD', error: 'only GET/POST/DELETE are supported' })
      return
    }

    const rel = pathname === routePrefix ? '/' : pathname.slice(routePrefix.length)

    if (method === 'GET' && (rel === '/health' || rel === '/health/')) {
      json(res, 200, {
        ok: true,
        plugin: name,
        active: true,
        version: BRIDGE_VERSION,
        sessionCount: sessions.size,
        autoReview: WANT_AUTO_REVIEW,
      })
      return
    }

    if (method === 'GET' && (rel === '/presets' || rel === '/presets/')) {
      json(res, 200, { ok: true, presets: [...dynamicPresets.keys()] })
      return
    }

    if (method === 'GET' && (rel === '/models' || rel === '/models/')) {
      try {
        const catalog = await controller.modelCatalog()
        json(res, 200, { ok: true, catalog })
      } catch (error) {
        json(res, 500, { ok: false, code: 'MODEL_CATALOG_FAILED', error: errorMessage(error) })
      }
      return
    }

    if (method === 'POST' && (rel === '/presets' || rel === '/presets/')) {
      let body
      try {
        body = await readJsonBody(req, 12 * 1024 * 1024)
      } catch (error) {
        json(res, 400, { ok: false, code: 'INVALID', error: errorMessage(error) })
        return
      }
      if (!agentPresets || typeof agentPresets.register !== 'function') {
        json(res, 503, { ok: false, code: 'PRESET_SERVICE_UNAVAILABLE', error: 'agentPresets service is unavailable' })
        return
      }
      const id = typeof body.id === 'string' ? body.id.trim() : ''
      const plugins = Array.isArray(body.plugins) ? body.plugins : null
      if (!id || !plugins) {
        json(res, 400, { ok: false, code: 'INVALID', error: 'id and plugins are required' })
        return
      }
      try {
        const previous = dynamicPresets.get(id)
        if (previous) {
          await previous()
          dynamicPresets.delete(id)
        }
        const dispose = await agentPresets.register({
          id,
          name: typeof body.name === 'string' ? body.name : id,
          description: typeof body.description === 'string' ? body.description : '',
          plugins,
        })
        dynamicPresets.set(id, dispose)
        json(res, 200, { ok: true, presetId: id, dynamic: true })
      } catch (error) {
        json(res, 500, { ok: false, code: 'PRESET_REGISTER_FAILED', error: errorMessage(error) })
      }
      return
    }

    if (method === 'POST' && (rel === '/sessions' || rel === '/sessions/')) {
      let body
      try {
        body = await readJsonBody(req, maxBodyBytes)
      } catch (error) {
        json(res, 400, { ok: false, code: 'INVALID', error: errorMessage(error) })
        return
      }
      if (sessions.size >= MAX_SESSIONS) {
        evictIdleSessions(sessions.size - MAX_SESSIONS + 1)
      }
      if (sessions.size >= MAX_SESSIONS) {
        json(res, 429, {
          ok: false,
          code: 'SESSION_LIMIT',
          error: `session limit reached (${MAX_SESSIONS})，且没有可回收的空闲会话`,
          sessionCount: sessions.size,
          maxSessions: MAX_SESSIONS,
        })
        return
      }
      let created
      let requestedCwd = ''
      try {
        const createOptions = {}
        if (typeof body.cwd === 'string' && body.cwd.trim().length > 0) createOptions.cwd = body.cwd.trim()
        if (typeof body.agentPreset === 'string' && body.agentPreset.trim().length > 0) createOptions.agentPreset = body.agentPreset.trim()
        requestedCwd = typeof createOptions.cwd === 'string' ? createOptions.cwd : ''
        created = await controller.create(createOptions)
      } catch (error) {
        json(res, 500, { ok: false, code: 'CREATE_FAILED', error: errorMessage(error) })
        return
      }
      const sessionId = created?.sessionId ?? created?.id
      if (typeof sessionId !== 'string' || sessionId.length === 0) {
        json(res, 500, { ok: false, code: 'CREATE_FAILED', error: 'sessionController.create returned no sessionId' })
        return
      }
      const session = {
        sessionId,
        agentPreset: created?.agentPreset ?? null,
        employeeId: typeof body.employeeId === 'string' ? body.employeeId : '',
        projectId: typeof body.projectId === 'string' ? body.projectId : '',
        cwd: requestedCwd,
        kind: typeof body.kind === 'string' ? body.kind : 'chat',
        turnKind: typeof body.kind === 'string' ? body.kind : 'chat',
        status: 'active',
        turnEnded: false,
        cancelRequested: false,
        error: null,
        frames: [],
        nextFrameIndex: 0,
        runningJobs: new Set(),
        lastFrameAt: Date.now(),
        followAbort: new AbortController(),
        followLoop: null,
        closed: false,
      }
      session.lastUsedAt = Date.now()
      sessions.set(sessionId, session)
      startFollowLoop(session)

      const text = typeof body.text === 'string' ? body.text : ''
      if (text.trim().length > 0) {
        try {
          await promptSession(session, text)
        } catch (error) {
          session.status = 'error'
          session.error = `prompt failed: ${errorMessage(error)}`
          json(res, 500, { ok: false, code: 'PROMPT_FAILED', error: session.error })
          return
        }
      }
      json(res, 200, { ok: true, sessionId, agentPreset: session.agentPreset })
      return
    }

    if (method === 'GET' && (rel === '/sessions' || rel === '/sessions/')) {
      json(res, 200, {
        ok: true,
        sessionCount: sessions.size,
        maxSessions: MAX_SESSIONS,
        sessions: [...sessions.values()].map((session) => ({
          sessionId: session.sessionId,
          employeeId: session.employeeId || '',
          projectId: session.projectId || '',
          cwd: session.cwd || '',
          status: session.status,
          turnEnded: session.turnEnded === true,
          lastUsedAt: session.lastUsedAt || 0,
          permissionPreset: session.permissionPreset || '',
          frames: session.frames.length,
          runningJobs: session.runningJobs ? session.runningJobs.size : 0,
          lastFrameAt: session.lastFrameAt || 0,
        })),
      })
      return
    }

    if (method === 'DELETE' && rel.startsWith('/sessions/')) {
      const id = decodeURIComponent(rel.slice('/sessions/'.length).replace(/\/$/, ''))
      const session = sessions.get(id)
      if (!session) {
        json(res, 404, { ok: false, code: 'NOT_FOUND', error: `unknown session: ${id}` })
        return
      }
      if (hasActiveTurn(session)) {
        json(res, 409, { ok: false, code: 'SESSION_BUSY', error: '会话正在执行，先 cancel 再删除' })
        return
      }
      evictSession(id, 'deleted')
      json(res, 200, { ok: true, sessionId: id, closed: true })
      return
    }

    const match = /^\/sessions\/([^/]+)(\/events|\/messages|\/cancel|\/result|\/model|\/resume|\/state)?\/?$/.exec(rel)
    if (!match) {
      json(res, 404, { ok: false, code: 'NOT_FOUND', error: `unknown route: ${pathname}` })
      return
    }
    const sessionId = decodeURIComponent(match[1])
    const action = match[2] ?? ''

    // 恢复一个已经落盘、但当前进程内存里还没有的 Session。
    // DSH 的控制器会从 session.v4.jsonl.zstd 重新打开同一个 sessionId，上下文不会丢。
    if (method === 'POST' && action === '/resume') {
      const existing = findSession(sessionId)
      if (existing) {
        json(res, 200, { ok: true, sessionId, resumed: true, lastIndex: existing.nextFrameIndex })
        return
      }
      // 不依赖 controller.resolve（SessionController 没暴露这个方法）；
      // 直接新建桥接记录并 follow：能读到持久化日志就是恢复成功，读不到会在 400ms 内变成 error。
      const session = {
        sessionId,
        agentPreset: null,
        employeeId: '',
        projectId: '',
        cwd: '',
        kind: 'chat',
        turnKind: 'chat',
        status: 'active',
        turnEnded: false,
        cancelRequested: false,
        error: null,
        frames: [],
        nextFrameIndex: 0,
        runningJobs: new Set(),
        lastFrameAt: Date.now(),
        followAbort: new AbortController(),
        followLoop: null,
        closed: false,
      }
      session.lastUsedAt = Date.now()
      sessions.set(sessionId, session)
      startFollowLoop(session)
      // 让 follow 先吐出 opening snapshot，再返回；这样调用方拿到的 lastIndex 不会重放历史。
      await new Promise((resolve) => setTimeout(resolve, 450))
      if (session.status === 'error') {
        sessions.delete(sessionId)
        json(res, 404, { ok: false, code: 'NOT_FOUND', error: session.error || `unknown session: ${sessionId}` })
        return
      }
      json(res, 200, { ok: true, sessionId, resumed: true, cwd: session.cwd, lastIndex: session.nextFrameIndex })
      return
    }

    const session = findSession(sessionId)
    if (!session) {
      json(res, 404, { ok: false, code: 'NOT_FOUND', error: `unknown session: ${sessionId}` })
      return
    }

    if (method === 'GET' && action === '/state') {
      json(res, 200, {
        ok: true,
        sessionId,
        status: session.status,
        turnEnded: session.turnEnded === true,
        frames: session.frames.length,
        nextFrameIndex: session.nextFrameIndex,
        runningJobs: session.runningJobs ? session.runningJobs.size : 0,
        lastFrameAt: session.lastFrameAt || 0,
        lastUsedAt: session.lastUsedAt || 0,
        cwd: session.cwd || '',
      })
      return
    }

    if (method === 'GET' && action === '/events') {
      const url = new URL(req.url || '/', 'http://127.0.0.1')
      const sinceRaw = url.searchParams.get('since')
      const since = sinceRaw === null ? 0 : Number(sinceRaw)
      if (!Number.isInteger(since) || since < 0) {
        json(res, 400, { ok: false, code: 'INVALID', error: 'since must be a non-negative integer' })
        return
      }
      const events = session.frames.filter((frame) => typeof frame.index === 'number' && frame.index >= since)
      const lastIndex = session.frames.length > 0 ? session.frames[session.frames.length - 1].index : since - 1
      json(res, 200, {
        ok: true,
        events,
        nextIndex: typeof lastIndex === 'number' ? lastIndex + 1 : since,
        status: session.status,
        turnEnded: session.turnEnded === true,
      })
      return
    }

    if (method === 'POST' && action === '/messages') {
      let body
      try {
        body = await readJsonBody(req, maxBodyBytes)
      } catch (error) {
        json(res, 400, { ok: false, code: 'INVALID', error: errorMessage(error) })
        return
      }
      const text = typeof body.text === 'string' ? body.text : ''
      session.turnKind = body.kind === 'chat' ? 'chat' : 'company'
      const mode = body.mode === 'steer' ? 'steer' : 'queue'
      const requestId = typeof body.requestId === 'string' ? body.requestId : ''
      const images = Array.isArray(body.images) ? body.images : []
      const content = []
      if (text.trim().length > 0) content.push({ type: 'text', text })
      for (const image of images.slice(0, 6)) {
        if (!image || typeof image.data !== 'string' || !image.data) continue
        if (!/^image\/(png|jpeg|jpg|webp|gif)$/i.test(String(image.mediaType || ''))) continue
        content.push({
          type: 'image',
          mediaType: String(image.mediaType).toLowerCase().replace('image/jpg', 'image/jpeg'),
          data: image.data,
          name: typeof image.name === 'string' ? image.name.slice(0, 120) : undefined,
        })
      }
      if (content.length === 0) {
        json(res, 400, { ok: false, code: 'INVALID', error: 'text or image is required' })
        return
      }
      try {
        await promptSession(session, content, mode, requestId)
      } catch (error) {
        json(res, 500, { ok: false, code: 'PROMPT_FAILED', error: errorMessage(error) })
        return
      }
      json(res, 200, { ok: true, accepted: true, sessionId, mode })
      return
    }

    if (method === 'POST' && action === '/cancel') {
      let value
      try {
        value = await controller.cancel({ sessionId })
      } catch (error) {
        json(res, 500, { ok: false, code: 'CANCEL_FAILED', error: errorMessage(error) })
        return
      }
      session.cancelRequested = session.status === 'active' || session.cancelRequested
      // cancel 在无活 turn 时可能 accepted=false（幂等语义：仍视为成功，不改变已完成状态）
      const accepted = value?.accepted === true
      if (accepted && session.status === 'active' && session.nextFrameIndex === 0) {
        // 首个 turn 尚未开始即取消：没有 turn/end 可等，直接收口为 cancelled
        session.status = 'cancelled'
      }
      json(res, 200, { ok: true, accepted, sessionId })
      return
    }

    if (method === 'POST' && action === '/model') {
      let body
      try {
        body = await readJsonBody(req, maxBodyBytes)
      } catch (error) {
        json(res, 400, { ok: false, code: 'INVALID', error: errorMessage(error) })
        return
      }
      const provider = typeof body.provider === 'string' ? body.provider.trim() : ''
      const model = typeof body.model === 'string' ? body.model.trim() : ''
      if (!provider || !model) {
        json(res, 400, { ok: false, code: 'INVALID', error: 'provider and model are required' })
        return
      }
      const reasoningEffort = typeof body.reasoningEffort === 'string' ? body.reasoningEffort.trim() : ''
      const request = { sessionId, provider, model }
      if (reasoningEffort) request.reasoningEffort = reasoningEffort
      try {
        let selected
        try {
          selected = await controller.selectModel(request)
        } catch (error) {
          // 模型不支持指定思考强度时，退回不带 effort 的选择
          if (!request.reasoningEffort) throw error
          delete request.reasoningEffort
          selected = await controller.selectModel(request)
        }
        session.model = selected?.selected?.model ?? model
        session.provider = selected?.selected?.provider ?? provider
        json(res, 200, { ok: true, sessionId, selected: selected?.selected ?? { provider, model } })
      } catch (error) {
        json(res, 500, { ok: false, code: 'MODEL_SELECT_FAILED', error: errorMessage(error) })
      }
      return
    }

    if (method === 'GET' && action === '/result') {
      const result = deriveResult(session)
      json(res, 200, { ok: true, sessionId, ...result })
      return
    }

    json(res, 404, { ok: false, code: 'NOT_FOUND', error: `unknown route: ${pathname}` })
  }

  ctx.effect(() => {
    const dispose = web.register({
      kind: 'prefix',
      path: routePrefix,
      handler: (req, res) => {
        Promise.resolve(handle(req, res, String(req.url || '/').split('?')[0]))
          .catch((error) => {
            if (!res.headersSent) json(res, 500, { ok: false, code: 'INTERNAL', error: errorMessage(error) })
            else res.end()
          })
      },
    })
    return () => {
      for (const session of sessions.values()) {
        session.closed = true
        try {
          session.followAbort.abort()
        } catch {
          /* teardown never throws */
        }
      }
      try {
        dispose()
      } catch {
        /* teardown never throws */
      }
    }
  }, 'opc-runtime-bridge: routes')
}
